mapper.select:
SELECT
*
FROM(
SELECT
a.BOOKSET_ID          AS booksetId, /**账套代码**/
a.HAPPEN_DATE         AS happenDate, /**发生日期**/
a.BOOK_DATE           AS bookDate, /**入账日期**/
a.BOOKSET_DATE        AS booksetDate, /**账套日期**/
a.PROFIT_TYPE         AS profitType, /**收益类型**/
a.CAPITAL             AS capital, /**实收资本**/
a.NET_ASSET_VALUE_BEF AS netAssetValueBef, /**费前资产净值**/
a.NET_ASSET_VALUE     AS netAssetValue, /**资产净值**/
a.NET_UNIT_VALUE_BEF  AS netUnitValueBef, /**费前单位净值**/
a.NET_UNIT_VALUE      AS netUnitValue, /**单位净值**/
a.P_YIELD_BEF         AS pYieldBef, /**万份收益_费前**/
a.P_YIELD             AS pYield, /**万份收益**/
a.TDY_YIELD_BEF       AS tdyYieldBef, /**当日年化收益率_费前**/
a.TDY_YIELD           AS tdyYield, /**当日年化收益率**/
a.YIELD_TERM_BEF      AS yieldTermBef, /**周期年化收益率_费前**/
a.YIELD_TERM          AS yieldTerm, /**周期年化收益率**/
a.YIELD_7_BEF         AS yield7Bef, /**当日7日年化收益率_费前**/
a.YIELD_7             AS yield7, /**当日7日年化收益率**/
a.TOT_BOUNS_AMT       AS totBounsAmt, /**累计分红金额**/
a.TDY_BOUNS_AMT       AS tdyBounsAmt, /**当日分红金额**/
a.TOT_BOUNS_NET       AS totBounsNet, /**累计分红净值**/
a.TDY_BOUNS_NET       AS tdyBounsNet, /**当日分红净值**/
a.PROFIT_AMT          AS profitAmt, /**应付利润**/
a.TOT_PROFIT_AMT      AS totProfitAmt, /**累计应付利润**/
a.INT_RATE            AS intRate, /**计提利率（当日发生）**/
rn
FROM /* 子查询必加上rn字段 */
SELECT result.* FROM (
SELECT tmp.*,
@rownum := @rownum + 1 row, /* 虚拟列行标 */
IF(
(
@BOOKSET_ID = tmp.BOOKSET_ID and
@HAPPEN_DATE = tmp.HAPPEN_DATE
),
@rank := @rank + 1,
@rank := 1
) AS rn, /* 分组虚拟列行标 */
/* 下面的分组条件需要与oracle中 over (PARTITION BY xxx,xxx,xxx)顺序保持一至 */
@BOOKSET_ID := tmp.BOOKSET_ID /* 分组条件1 */
, @HAPPEN_DATE := tmp.HAPPEN_DATE /* 分组条件2 */
FROM (
/* 数据源 */
SELECT bc.*
FROM BOK_STAT_BOK_POSITION bc
ORDER BY CAST(bc.BOOKSET_DATE as SIGNED) DESC /* 按实际情况与oracle保持一至的排序 */
) tmp,
/* 定义临时变量池 */
(SELECT @rownum := 0,
@BOOKSET_ID := null,
@HAPPEN_DATE = null,
@rank := 0) a
) result
) a
WHERE
1 = 1

    AND a.HAPPEN_DATE <= #{sdateEnd}


    AND a.HAPPEN_DATE >= #{sdateStart}


    AND a.HAPPEN_DATE IN

        #{item}



    AND a.BOOKSET_ID = #{booksetId}


    AND a.BOOK_DATE <= #{bookDate}


    AND a.FINPROD_ID = #{finprodId}


    AND a.layering_Id = #{layeringId}


    AND a.is_sub_prd = #{isSubPrd}

)
WHERE  rn = 1
